impl PqMode {
    fn from_env(enabled: bool) -> Self {
        if !enabled {
            return Self::Off;
        }

        let mode = std::env::var(ANN_PQ_MODE_ENV)
            .unwrap_or_else(|_| "primary_residual".to_string())
            .trim()
            .to_ascii_lowercase();
        match mode.as_str() {
            "global" => Self::Global,
            "primary" | "primary_residual" | "primary-residual" | "" => Self::PrimaryResidual,
            _ => Self::PrimaryResidual,
        }
    }
}

